/**
 * Shared types mirroring `meteoswiss-mcp`'s `getLocalForecast` output shape
 * (see packages/meteoswiss-mcp/src/schemas/ogd-local-forecast.ts, added in PR #99).
 *
 * Deliberately duplicated rather than imported: this eval package must NOT depend on
 * meteoswiss-mcp's source so it can live on a `main`-based branch, independent of #99.
 * The fixtures under fixtures/ are static JSON captured from a real tool run (see
 * PLAN.md "Fixture & the two variants"), not generated by importing #99's code at eval time.
 */

/** A single hourly precipitation reading within a day. */
export type HourlyPrecip = {
  time: string;
  value: number;
};

/** Daily forecast summary for one day, as returned by `meteoswissLocalForecast`. */
export type DailyForecast = {
  date: string;
  weather: string | null;
  weather_icon_url: string | null;
  temperature: { min: number | null; max: number | null; unit: string };
  precipitation: {
    total: number | null;
    unit: string;
    hourly: HourlyPrecip[] | null;
  };
};

/** Full forecast response, as returned by `meteoswissLocalForecast`. */
export type LocalForecastResponse = {
  location: {
    name: string;
    type: string;
    elevation: number;
    coordinates: { lat: number; lon: number };
  };
  generated: string;
  forecast: DailyForecast[];
  source: string;
};

export function isLocalForecastResponse(
  value: unknown,
): value is LocalForecastResponse {
  return (
    typeof value === "object" &&
    value !== null &&
    "location" in value &&
    "forecast" in value &&
    Array.isArray((value as { forecast: unknown }).forecast)
  );
}
